    "schemaSnippet": "`BudgetAllocations_Logistics (dept_id VARCHAR(32) PRIMARY KEY, dept_name VARCHAR(64), allocated_usd DECIMAL(12,2))` & `ActualSpend_Logistics (dept_id VARCHAR(32), actual_usd DECIMAL(12,2))`",
    "targetQuery": "SELECT b.dept_id, b.dept_name,\n       b.allocated_usd,\n       COALESCE(SUM(s.actual_usd), 0.00) AS total_actual_spend,\n       b.allocated_usd - COALESCE(SUM(s.actual_usd), 0.00) AS remaining_budget,\n       CASE\n         WHEN COALESCE(SUM(s.actual_usd), 0.00) > b.allocated_usd THEN 'OVER_BUDGET'\n         WHEN COALESCE(SUM(s.actual_usd), 0.00) = 0.00 THEN 'ZERO_SPEND'\n         ELSE 'WITHIN_BUDGET'\n       END AS variance_audit_tag\nFROM BudgetAllocations_Logistics b\nLEFT JOIN ActualSpend_Logistics s\n  ON b.dept_id = s.dept_id\nGROUP BY b.dept_id, b.dept_name, b.allocated_usd\nORDER BY remaining_budget ASC;",
